#!/bin/bash
# macvm tek dosya kurulum: unzip gerekmez.  Kullanim (root):  bash macvm-kur.sh
# Sequoia icin:  MACOS=sequoia bash macvm-kur.sh
set -e
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH"
[ "$(id -u)" -eq 0 ] || { echo "root olarak calistir:  su -   sonra   bash macvm-kur.sh"; exit 1; }
D=/root/macvm-kurulum
rm -rf "$D"; mkdir -p "$D"
sed -n '/^__ARSIV__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$D"
cd "$D/macvm"
exec bash install.sh
